import{_ as e,o,c as a,a0 as d}from"./chunks/framework.LceoKIk6.js";const g=JSON.parse('{"title":"Estudio Competitivo — Editores Científicos y Notebooks","description":"","frontmatter":{},"headers":[],"relativePath":"COMPETITIVE_STUDY.md","filePath":"COMPETITIVE_STUDY.md"}'),i={name:"COMPETITIVE_STUDY.md"};function r(l,t,n,s,c,u){return o(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="estudio-competitivo-—-editores-cientificos-y-notebooks" tabindex="-1">Estudio Competitivo — Editores Científicos y Notebooks <a class="header-anchor" href="#estudio-competitivo-—-editores-cientificos-y-notebooks" aria-label="Permalink to &quot;Estudio Competitivo — Editores Científicos y Notebooks&quot;">​</a></h1><blockquote><p>Objetivo: identificar las fortalezas y debilidades de cada competidor para construir el mejor editor científico de notebooks del mercado.</p></blockquote><hr><h2 id="_1-panorama-del-mercado" tabindex="-1">1. Panorama del Mercado <a class="header-anchor" href="#_1-panorama-del-mercado" aria-label="Permalink to &quot;1. Panorama del Mercado&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Producto</th><th>Tipo</th><th>Open Source</th><th>Foco Principal</th></tr></thead><tbody><tr><td><strong>Jupyter Notebook/Lab</strong></td><td>Notebook computacional</td><td>Sí</td><td>Ejecución de código + visualización</td></tr><tr><td><strong>Notion</strong></td><td>Docs/Wiki colaborativo</td><td>No</td><td>Productividad general, bloques</td></tr><tr><td><strong>Overleaf</strong></td><td>Editor LaTeX online</td><td>Parcial</td><td>Documentos académicos LaTeX</td></tr><tr><td><strong>Mathcha</strong></td><td>Editor matemático visual</td><td>No</td><td>Fórmulas + diagramas WYSIWYG</td></tr><tr><td><strong>Observable</strong></td><td>Notebook reactivo</td><td>Parcial</td><td>Visualización de datos, JS</td></tr><tr><td><strong>Quarto</strong></td><td>Publishing científico</td><td>Sí</td><td>Documentos reproducibles multi-lenguaje</td></tr><tr><td><strong>Typst</strong></td><td>Lenguaje de composición</td><td>Sí</td><td>Alternativa moderna a LaTeX</td></tr><tr><td><strong>CoCalc</strong></td><td>Plataforma colaborativa</td><td>Parcial</td><td>Jupyter + LaTeX + terminal en la nube</td></tr><tr><td><strong>Deepnote</strong></td><td>Notebook colaborativo</td><td>No</td><td>Jupyter en la nube + colaboración</td></tr><tr><td><strong>HackMD/CodiMD</strong></td><td>Markdown colaborativo</td><td>Sí</td><td>Markdown en tiempo real</td></tr></tbody></table><hr><h2 id="_2-analisis-detallado-por-competidor" tabindex="-1">2. Análisis Detallado por Competidor <a class="header-anchor" href="#_2-analisis-detallado-por-competidor" aria-label="Permalink to &quot;2. Análisis Detallado por Competidor&quot;">​</a></h2><h3 id="_2-1-jupyter-notebook-jupyterlab" tabindex="-1">2.1 Jupyter Notebook / JupyterLab <a class="header-anchor" href="#_2-1-jupyter-notebook-jupyterlab" aria-label="Permalink to &quot;2.1 Jupyter Notebook / JupyterLab&quot;">​</a></h3><p><strong>Fortalezas:</strong></p><ul><li>Estándar de facto para computación científica</li><li>Ejecución de código en 100+ lenguajes vía kernels</li><li>Ecosistema masivo de extensiones</li><li>Formato <code>.ipynb</code> ampliamente adoptado</li><li>Rich output: gráficos, tablas, widgets interactivos</li></ul><p><strong>Debilidades:</strong></p><ul><li>UX anticuada — la edición de texto es tosca</li><li>Sin WYSIWYG para Markdown (edit/preview separados)</li><li>LaTeX solo en preview, no hay editor visual de fórmulas</li><li>Sin drag &amp; drop para reordenar celdas (JupyterLab lo agregó parcialmente)</li><li>Sin toolbar flotante contextual</li><li>Temas limitados, personalización CSS manual</li><li>Sin colaboración en tiempo real (JupyterLab tiene extensión experimental)</li><li>Arranque lento (servidor Python + kernel)</li></ul><p><strong>Oportunidad para sci-notebook:</strong></p><ul><li>UX moderna con click-to-edit, toolbar flotante, insert handles</li><li>Editor visual de fórmulas que Jupyter no tiene</li><li>Arranque instantáneo (sin servidor, puro frontend)</li><li>Mejor experiencia mobile</li></ul><hr><h3 id="_2-2-notion" tabindex="-1">2.2 Notion <a class="header-anchor" href="#_2-2-notion" aria-label="Permalink to &quot;2.2 Notion&quot;">​</a></h3><p><strong>Fortalezas:</strong></p><ul><li>UX excepcional — el estándar de oro en edición por bloques</li><li>Slash commands (<code>/</code>) para insertar cualquier tipo de bloque</li><li>Drag &amp; drop fluido para reordenar</li><li>Inline databases, tablas, kanban, calendarios</li><li>Colaboración en tiempo real</li><li>Templates reutilizables</li><li>API pública robusta</li></ul><p><strong>Debilidades:</strong></p><ul><li>Sin soporte nativo de LaTeX (solo inline con <code>$$</code>, rendering básico)</li><li>Sin ejecución de código</li><li>Sin editor visual de fórmulas (solo raw LaTeX)</li><li>Cerrado, propietario, vendor lock-in</li><li>Sin modo offline robusto</li><li>Rendering de fórmulas lento comparado con KaTeX nativo</li><li>Sin syntax highlighting avanzado para código</li></ul><p><strong>Oportunidad para sci-notebook:</strong></p><ul><li>Adoptar la UX de bloques de Notion pero con foco científico</li><li>Editor visual de fórmulas &gt;&gt;&gt; lo que Notion ofrece</li><li>Open source, sin vendor lock-in</li><li>Mejor soporte de código con syntax highlighting real</li></ul><hr><h3 id="_2-3-overleaf" tabindex="-1">2.3 Overleaf <a class="header-anchor" href="#_2-3-overleaf" aria-label="Permalink to &quot;2.3 Overleaf&quot;">​</a></h3><p><strong>Fortalezas:</strong></p><ul><li>Editor LaTeX colaborativo líder del mercado</li><li>Compilación en tiempo real con preview PDF</li><li>Miles de templates académicos</li><li>Integración con journals para submission directa</li><li>Git sync, Dropbox sync</li><li>Historial de versiones completo</li></ul><p><strong>Debilidades:</strong></p><ul><li>Curva de aprendizaje alta (requiere saber LaTeX)</li><li>Sin modo WYSIWYG real (el &quot;rich text&quot; es limitado)</li><li>Sin celdas/bloques — es un editor de texto plano</li><li>Sin ejecución de código</li><li>Sin embeds interactivos</li><li>Lento para documentos grandes</li><li>Interfaz datada, no moderna</li></ul><p><strong>Oportunidad para sci-notebook:</strong></p><ul><li>Editor visual de fórmulas que elimina la barrera de LaTeX</li><li>Estructura por celdas más flexible que texto plano</li><li>Embeds interactivos (gráficos, videos, iframes)</li><li>Rendimiento superior (no necesita compilar PDF)</li></ul><hr><h3 id="_2-4-mathcha" tabindex="-1">2.4 Mathcha <a class="header-anchor" href="#_2-4-mathcha" aria-label="Permalink to &quot;2.4 Mathcha&quot;">​</a></h3><p><strong>Fortalezas:</strong></p><ul><li>Editor WYSIWYG de matemáticas más intuitivo del mercado</li><li>Paleta visual de símbolos y estructuras</li><li>Diagramas integrados (tikz-like)</li><li>Export a LaTeX, PDF, imagen</li><li>Sin necesidad de saber LaTeX para escribir fórmulas</li></ul><p><strong>Debilidades:</strong></p><ul><li>Solo fórmulas y diagramas — no es un notebook completo</li><li>Sin celdas de código</li><li>Sin Markdown</li><li>Sin plugins ni extensibilidad</li><li>Sin API programática</li><li>Cerrado, propietario</li><li>Sin colaboración en tiempo real</li></ul><p><strong>Oportunidad para sci-notebook:</strong></p><ul><li>Combinar la UX de fórmulas de Mathcha con un notebook completo</li><li>Nuestro MathEditor ya tiene paleta de bloques similar</li><li>Agregar: drag &amp; drop de bloques de fórmula, preview en tiempo real</li><li>Extensible vía plugins</li></ul><hr><h3 id="_2-5-observable" tabindex="-1">2.5 Observable <a class="header-anchor" href="#_2-5-observable" aria-label="Permalink to &quot;2.5 Observable&quot;">​</a></h3><p><strong>Fortalezas:</strong></p><ul><li>Notebooks reactivos — las celdas se actualizan automáticamente</li><li>Visualización de datos de primera clase (D3, Plot)</li><li>Importación de notebooks entre usuarios</li><li>Ejecución JavaScript nativa en el browser</li><li>Comunidad activa de visualización</li></ul><p><strong>Debilidades:</strong></p><ul><li>Solo JavaScript (no Python, R, etc.)</li><li>Sin soporte robusto de LaTeX</li><li>Sin editor visual de fórmulas</li><li>Modelo de datos propietario (no .ipynb)</li><li>Sin modo offline</li><li>Curva de aprendizaje para el modelo reactivo</li></ul><p><strong>Oportunidad para sci-notebook:</strong></p><ul><li>Soporte multi-formato (Markdown + LaTeX + código + embeds)</li><li>Editor visual de fórmulas</li><li>Formato JSON estándar, portable</li><li>Embeds de Observable como iframe</li></ul><hr><h3 id="_2-6-quarto" tabindex="-1">2.6 Quarto <a class="header-anchor" href="#_2-6-quarto" aria-label="Permalink to &quot;2.6 Quarto&quot;">​</a></h3><p><strong>Fortalezas:</strong></p><ul><li>Publishing científico de primera clase</li><li>Multi-lenguaje (Python, R, Julia, Observable JS)</li><li>Output a HTML, PDF, Word, presentaciones, libros</li><li>Integración con Jupyter kernels</li><li>Cross-references, citaciones, bibliografía</li><li>Extensible vía Lua filters</li></ul><p><strong>Debilidades:</strong></p><ul><li>No es un editor — es un sistema de build/publishing</li><li>Requiere CLI + editor externo (VS Code, RStudio)</li><li>Sin UX interactiva en el browser</li><li>Sin editor visual de fórmulas</li><li>Sin drag &amp; drop</li><li>Sin colaboración en tiempo real</li></ul><p><strong>Oportunidad para sci-notebook:</strong></p><ul><li>Ser el editor visual que Quarto necesita como frontend</li><li>UX interactiva que Quarto no tiene</li><li>Posible integración: exportar a formato Quarto (.qmd)</li></ul><hr><h3 id="_2-7-typst" tabindex="-1">2.7 Typst <a class="header-anchor" href="#_2-7-typst" aria-label="Permalink to &quot;2.7 Typst&quot;">​</a></h3><p><strong>Fortalezas:</strong></p><ul><li>Alternativa moderna a LaTeX con sintaxis más simple</li><li>Compilación incremental ultra-rápida</li><li>Preview en tiempo real</li><li>Funciones y scripting integrados</li><li>Mejor manejo de errores que LaTeX</li><li>Open source</li></ul><p><strong>Debilidades:</strong></p><ul><li>Ecosistema joven, pocos packages</li><li>Sin editor visual de fórmulas</li><li>Sin modelo de celdas/notebook</li><li>Sin ejecución de código externo</li><li>Adopción limitada vs LaTeX</li></ul><p><strong>Oportunidad para sci-notebook:</strong></p><ul><li>Posible plugin para renderizar Typst además de LaTeX</li><li>Nuestro editor visual de fórmulas es algo que Typst no tiene</li><li>Modelo de celdas más flexible</li></ul><hr><h3 id="_2-8-cocalc" tabindex="-1">2.8 CoCalc <a class="header-anchor" href="#_2-8-cocalc" aria-label="Permalink to &quot;2.8 CoCalc&quot;">​</a></h3><p><strong>Fortalezas:</strong></p><ul><li>Jupyter + LaTeX + terminal + chat en una plataforma</li><li>Colaboración en tiempo real con CRDT</li><li>Historial de versiones granular</li><li>Soporte para Sage, R, Julia, Octave</li><li>TimeTravel (replay de ediciones)</li></ul><p><strong>Debilidades:</strong></p><ul><li>UX compleja, sobrecargada</li><li>Lento (servidor remoto obligatorio)</li><li>Sin editor visual de fórmulas</li><li>Interfaz anticuada</li><li>Requiere cuenta y conexión</li></ul><p><strong>Oportunidad para sci-notebook:</strong></p><ul><li>UX limpia y moderna vs la complejidad de CoCalc</li><li>Funciona offline, sin servidor</li><li>Editor visual de fórmulas</li></ul><hr><h2 id="_3-matriz-comparativa-de-features" tabindex="-1">3. Matriz Comparativa de Features <a class="header-anchor" href="#_3-matriz-comparativa-de-features" aria-label="Permalink to &quot;3. Matriz Comparativa de Features&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Jupyter</th><th>Notion</th><th>Overleaf</th><th>Mathcha</th><th>Observable</th><th>Quarto</th><th>Typst</th><th>CoCalc</th><th><strong>sci-notebook</strong></th></tr></thead><tbody><tr><td><strong>Celdas/Bloques</strong></td><td>✅</td><td>✅</td><td>❌</td><td>❌</td><td>✅</td><td>✅</td><td>❌</td><td>✅</td><td>✅</td></tr><tr><td><strong>Markdown WYSIWYG</strong></td><td>❌</td><td>✅</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td></tr><tr><td><strong>LaTeX rendering</strong></td><td>✅</td><td>⚠️</td><td>✅</td><td>✅</td><td>⚠️</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td><strong>Editor visual fórmulas</strong></td><td>❌</td><td>❌</td><td>❌</td><td>✅</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td></tr><tr><td><strong>Paleta de símbolos</strong></td><td>❌</td><td>❌</td><td>❌</td><td>✅</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td></tr><tr><td><strong>Celdas de imagen</strong></td><td>✅</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td><strong>Drag &amp; drop imágenes</strong></td><td>❌</td><td>✅</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td></tr><tr><td><strong>Embeds/iframes</strong></td><td>⚠️</td><td>✅</td><td>❌</td><td>❌</td><td>✅</td><td>✅</td><td>❌</td><td>❌</td><td>✅</td></tr><tr><td><strong>Toolbar flotante</strong></td><td>❌</td><td>✅</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td></tr><tr><td><strong>Insert handles</strong></td><td>❌</td><td>✅</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td></tr><tr><td><strong>Click-to-edit</strong></td><td>❌</td><td>✅</td><td>N/A</td><td>N/A</td><td>❌</td><td>N/A</td><td>N/A</td><td>❌</td><td>✅</td></tr><tr><td><strong>Drag reorder</strong></td><td>⚠️</td><td>✅</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td></tr><tr><td><strong>Keyboard nav</strong></td><td>✅</td><td>✅</td><td>✅</td><td>⚠️</td><td>⚠️</td><td>N/A</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td><strong>Temas light/dark</strong></td><td>⚠️</td><td>✅</td><td>❌</td><td>❌</td><td>✅</td><td>✅</td><td>✅</td><td>⚠️</td><td>✅</td></tr><tr><td><strong>Ejecución de código</strong></td><td>✅</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td><strong>Colaboración RT</strong></td><td>❌</td><td>✅</td><td>✅</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td><td>🔜</td></tr><tr><td><strong>Open source</strong></td><td>✅</td><td>❌</td><td>⚠️</td><td>❌</td><td>⚠️</td><td>✅</td><td>✅</td><td>⚠️</td><td>✅</td></tr><tr><td><strong>Sin servidor</strong></td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td></tr><tr><td><strong>Plugin system</strong></td><td>✅</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td><td>✅</td><td>❌</td><td>✅</td></tr><tr><td><strong>AI integration</strong></td><td>⚠️</td><td>✅</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>⚠️</td><td>✅</td></tr><tr><td><strong>Framework agnostic</strong></td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td></tr></tbody></table><p><strong>Leyenda:</strong> ✅ = Sí | ⚠️ = Parcial | ❌ = No | 🔜 = Planeado</p><hr><h2 id="_4-ventajas-competitivas-unicas-de-sci-notebook" tabindex="-1">4. Ventajas Competitivas Únicas de sci-notebook <a class="header-anchor" href="#_4-ventajas-competitivas-unicas-de-sci-notebook" aria-label="Permalink to &quot;4. Ventajas Competitivas Únicas de sci-notebook&quot;">​</a></h2><h3 id="_4-1-lo-que-nadie-mas-tiene-combinado" tabindex="-1">4.1 Lo que NADIE más tiene (combinado) <a class="header-anchor" href="#_4-1-lo-que-nadie-mas-tiene-combinado" aria-label="Permalink to &quot;4.1 Lo que NADIE más tiene (combinado)&quot;">​</a></h3><ol><li><p><strong>Editor visual de fórmulas + notebook</strong>: Solo Mathcha tiene editor visual, pero no es un notebook. Solo Jupyter tiene notebook, pero no tiene editor visual. <strong>sci-notebook es el único que combina ambos.</strong></p></li><li><p><strong>Framework agnostic + sin servidor</strong>: Funciona 100% en el browser sin backend. Ningún competidor ofrece esto con el mismo nivel de features.</p></li><li><p><strong>Plugin system + UX moderna</strong>: La extensibilidad de Jupyter con la UX de Notion.</p></li><li><p><strong>Open source + foco científico</strong>: Quarto es open source pero no es un editor. Jupyter es open source pero la UX es anticuada.</p></li></ol><h3 id="_4-2-diferenciadores-clave" tabindex="-1">4.2 Diferenciadores Clave <a class="header-anchor" href="#_4-2-diferenciadores-clave" aria-label="Permalink to &quot;4.2 Diferenciadores Clave&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Diferenciador</th><th>Descripción</th></tr></thead><tbody><tr><td><strong>MathEditor visual</strong></td><td>9 categorías, 100+ bloques, preview en tiempo real, modo dual (visual/raw)</td></tr><tr><td><strong>Zero-server</strong></td><td>Puro TypeScript, funciona offline, embed en cualquier app</td></tr><tr><td><strong>Micro-bundle</strong></td><td>Core ~25KB, React adapter ~54KB, vs Jupyter (MB de Python + JS)</td></tr><tr><td><strong>Instant boot</strong></td><td>Sin kernel startup, sin compilación, rendering inmediato</td></tr><tr><td><strong>Composable</strong></td><td>Cada feature es un plugin opt-in, tree-shakeable</td></tr></tbody></table><hr><h2 id="_5-gaps-identificados-—-que-nos-falta" tabindex="-1">5. Gaps Identificados — Qué Nos Falta <a class="header-anchor" href="#_5-gaps-identificados-—-que-nos-falta" aria-label="Permalink to &quot;5. Gaps Identificados — Qué Nos Falta&quot;">​</a></h2><h3 id="_5-1-criticos-necesarios-para-competir" tabindex="-1">5.1 Críticos (necesarios para competir) <a class="header-anchor" href="#_5-1-criticos-necesarios-para-competir" aria-label="Permalink to &quot;5.1 Críticos (necesarios para competir)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Gap</th><th>Competidor referencia</th><th>Prioridad</th></tr></thead><tbody><tr><td>G1</td><td><strong>Slash commands</strong> (<code>/</code> para insertar)</td><td>Notion</td><td>🔴 Alta</td></tr><tr><td>G2</td><td><strong>Drag &amp; drop reorder</strong> de celdas</td><td>Notion, JupyterLab</td><td>🔴 Alta</td></tr><tr><td>G3</td><td><strong>Ejecución de código</strong> (al menos JS/Python vía Pyodide)</td><td>Jupyter, Observable</td><td>🔴 Alta</td></tr><tr><td>G4</td><td><strong>Syntax highlighting</strong> en celdas de código</td><td>Jupyter, VS Code</td><td>🔴 Alta</td></tr><tr><td>G5</td><td><strong>Export</strong> a PDF, HTML, Markdown, .ipynb</td><td>Quarto, Jupyter</td><td>🔴 Alta</td></tr><tr><td>G6</td><td><strong>Colaboración en tiempo real</strong> (Yjs/CRDT)</td><td>Notion, Overleaf, CoCalc</td><td>🟡 Media</td></tr></tbody></table><h3 id="_5-2-importantes-diferenciadores-de-calidad" tabindex="-1">5.2 Importantes (diferenciadores de calidad) <a class="header-anchor" href="#_5-2-importantes-diferenciadores-de-calidad" aria-label="Permalink to &quot;5.2 Importantes (diferenciadores de calidad)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Gap</th><th>Competidor referencia</th><th>Prioridad</th></tr></thead><tbody><tr><td>G7</td><td><strong>Table editor</strong> interactivo dentro de celdas</td><td>Notion</td><td>🟡 Media</td></tr><tr><td>G8</td><td><strong>Mermaid diagrams</strong> rendering</td><td>Jupyter, Quarto</td><td>🟡 Media</td></tr><tr><td>G9</td><td><strong>TOC sidebar</strong> (tabla de contenidos)</td><td>Notion, JupyterLab</td><td>🟡 Media</td></tr><tr><td>G10</td><td><strong>Find &amp; replace</strong> across cells</td><td>Overleaf, Jupyter</td><td>🟡 Media</td></tr><tr><td>G11</td><td><strong>Cell output</strong> display (para ejecución)</td><td>Jupyter</td><td>🟡 Media</td></tr><tr><td>G12</td><td><strong>Version history</strong> / diffing</td><td>Overleaf, CoCalc</td><td>🟡 Media</td></tr></tbody></table><h3 id="_5-3-nice-to-have-polish" tabindex="-1">5.3 Nice-to-have (polish) <a class="header-anchor" href="#_5-3-nice-to-have-polish" aria-label="Permalink to &quot;5.3 Nice-to-have (polish)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Gap</th><th>Competidor referencia</th><th>Prioridad</th></tr></thead><tbody><tr><td>G13</td><td><strong>Presentation mode</strong> (slideshow)</td><td>Jupyter RISE</td><td>🟢 Baja</td></tr><tr><td>G14</td><td><strong>Comments / annotations</strong></td><td>Notion, Google Docs</td><td>🟢 Baja</td></tr><tr><td>G15</td><td><strong>Templates</strong> gallery</td><td>Notion, Overleaf</td><td>🟢 Baja</td></tr><tr><td>G16</td><td><strong>Mobile-optimized</strong> UI</td><td>Notion</td><td>🟢 Baja</td></tr><tr><td>G17</td><td><strong>Autocomplete</strong> para LaTeX commands</td><td>Overleaf</td><td>🟢 Baja</td></tr><tr><td>G18</td><td><strong>Citation management</strong> (BibTeX)</td><td>Overleaf, Quarto</td><td>🟢 Baja</td></tr></tbody></table><hr><h2 id="_6-estrategia-—-como-ser-el-mejor" tabindex="-1">6. Estrategia — Cómo Ser el Mejor <a class="header-anchor" href="#_6-estrategia-—-como-ser-el-mejor" aria-label="Permalink to &quot;6. Estrategia — Cómo Ser el Mejor&quot;">​</a></h2><h3 id="fase-inmediata-v0-2-✅-completada" tabindex="-1">Fase Inmediata (v0.2) ✅ COMPLETADA <a class="header-anchor" href="#fase-inmediata-v0-2-✅-completada" aria-label="Permalink to &quot;Fase Inmediata (v0.2) ✅ COMPLETADA&quot;">​</a></h3><ul><li>[x] <strong>G1</strong>: Slash commands — SlashCommand.tsx con 8 tipos, filtro, keyboard nav</li><li>[x] <strong>G2</strong>: Drag &amp; drop reorder con indicador top/bottom</li><li>[x] <strong>G4</strong>: Syntax highlighting con Shiki (lazy loading, 30+ lenguajes)</li><li>[x] <strong>G8</strong>: Mermaid diagrams — renderMermaidFallback() en pipeline</li></ul><h3 id="fase-corta-v0-3-✅-completada" tabindex="-1">Fase Corta (v0.3) ✅ COMPLETADA <a class="header-anchor" href="#fase-corta-v0-3-✅-completada" aria-label="Permalink to &quot;Fase Corta (v0.3) ✅ COMPLETADA&quot;">​</a></h3><ul><li>[x] <strong>G3</strong>: Ejecución de código JS en sandbox + custom language executors</li><li>[x] <strong>G5</strong>: Export a HTML standalone + Markdown + .ipynb + JSON</li><li>[x] <strong>G7</strong>: Table editor interactivo — TableCell.tsx</li><li>[x] <strong>G9</strong>: TOC sidebar — TOCSidebar.tsx</li></ul><h3 id="fase-media-v0-4-✅-completada" tabindex="-1">Fase Media (v0.4) ✅ COMPLETADA <a class="header-anchor" href="#fase-media-v0-4-✅-completada" aria-label="Permalink to &quot;Fase Media (v0.4) ✅ COMPLETADA&quot;">​</a></h3><ul><li>[x] <strong>G10</strong>: Find &amp; replace global — FindReplace.tsx con Ctrl+F</li><li>[x] <strong>G11</strong>: Cell outputs — CellOutputDisplay.tsx (stream/display/error)</li><li>[x] <strong>G17</strong>: Autocomplete LaTeX — 120+ comandos en 8 categorías</li><li>[x] <strong>G12</strong>: Version history — VersionHistory con save/restore/diff</li></ul><h3 id="fase-larga-v1-0-—-pendiente" tabindex="-1">Fase Larga (v1.0) — Pendiente <a class="header-anchor" href="#fase-larga-v1-0-—-pendiente" aria-label="Permalink to &quot;Fase Larga (v1.0) — Pendiente&quot;">​</a></h3><ul><li>[ ] <strong>G6</strong>: Colaboración en tiempo real (Yjs)</li><li>[ ] <strong>G13</strong>: Presentation mode</li><li>[ ] <strong>G14</strong>: Comments</li><li>[ ] <strong>G18</strong>: Citations</li></ul><hr><h2 id="_7-principios-de-diseno-para-el-mejor-editor" tabindex="-1">7. Principios de Diseño para &quot;El Mejor Editor&quot; <a class="header-anchor" href="#_7-principios-de-diseno-para-el-mejor-editor" aria-label="Permalink to &quot;7. Principios de Diseño para &quot;El Mejor Editor&quot;&quot;">​</a></h2><ol><li><strong>Instant feedback</strong>: Cada acción del usuario produce resultado visual inmediato (&lt;16ms)</li><li><strong>Zero friction</strong>: Nunca más de 2 clicks para cualquier operación común</li><li><strong>Progressive disclosure</strong>: Simple por defecto, potente cuando lo necesitas</li><li><strong>Keyboard-first</strong>: Todo accesible por teclado, mouse es opcional</li><li><strong>Offline-first</strong>: Funciona sin conexión, sync cuando hay red</li><li><strong>Composable</strong>: Cada feature es un plugin, nada es obligatorio</li><li><strong>Beautiful defaults</strong>: Se ve profesional sin configuración</li><li><strong>Accessible</strong>: WCAG 2.1 AA, screen readers, high contrast</li><li><strong>Fast</strong>: &lt;100ms para cualquier operación, &lt;1s para boot</li><li><strong>Open</strong>: Formato JSON estándar, sin vendor lock-in, MIT license</li></ol><hr><h2 id="_8-conclusion" tabindex="-1">8. Conclusión <a class="header-anchor" href="#_8-conclusion" aria-label="Permalink to &quot;8. Conclusión&quot;">​</a></h2><p>sci-notebook ocupa un nicho único: <strong>editor científico de notebooks con UX moderna, editor visual de fórmulas, y arquitectura de plugins — todo sin servidor, open source, y framework agnostic</strong>.</p><p>Ningún competidor combina estas características. La estrategia es:</p><ol><li>Mantener las ventajas únicas (MathEditor, zero-server, plugins)</li><li>Cerrar los gaps críticos (slash commands, drag reorder, code execution, syntax highlighting)</li><li>Pulir la UX hasta superar a Notion en el nicho científico</li><li>Construir comunidad con docs excelentes y ejemplos funcionales</li></ol>',106)])])}const m=e(i,[["render",r]]);export{g as __pageData,m as default};
